// ============================================================================
// FIST OF DOOM: TORONTO — REAL-WORLD CITY BUILDER
// Builds the CN Tower / Union Station district from OpenStreetMap data
// (window.TORONTO_MAP, generated by tools/fetch_toronto.py).
// Map data (c) OpenStreetMap contributors, ODbL.
// ============================================================================
(function () {
  'use strict';

  // ---------- Small helpers ----------
  function hash(n) {
    const s = Math.sin(n * 127.1 + 311.7) * 43758.5453;
    return s - Math.floor(s);
  }

  function polyArea(pts) {
    let a = 0;
    for (let i = 0, n = pts.length; i < n; i++) {
      const p = pts[i], q = pts[(i + 1) % n];
      a += p[0] * q[1] - q[0] * p[1];
    }
    return a / 2;
  }

  function centroid(pts) {
    let x = 0, z = 0;
    pts.forEach(p => { x += p[0]; z += p[1]; });
    return [x / pts.length, z / pts.length];
  }

  function pointInPoly(x, z, pts) {
    let inside = false;
    for (let i = 0, j = pts.length - 1; i < pts.length; j = i++) {
      const xi = pts[i][0], zi = pts[i][1], xj = pts[j][0], zj = pts[j][1];
      if (((zi > z) !== (zj > z)) && (x < (xj - xi) * (z - zi) / (zj - zi) + xi)) inside = !inside;
    }
    return inside;
  }

  function distToSegSq(px, pz, ax, az, bx, bz) {
    const dx = bx - ax, dz = bz - az;
    const l2 = dx * dx + dz * dz;
    let t = l2 > 0 ? ((px - ax) * dx + (pz - az) * dz) / l2 : 0;
    t = Math.max(0, Math.min(1, t));
    const cx = ax + t * dx - px, cz = az + t * dz - pz;
    return cx * cx + cz * cz;
  }

  function toPairs(flat) {
    const out = [];
    for (let i = 0; i < flat.length; i += 2) out.push([flat[i], flat[i + 1]]);
    return out;
  }

  // Geometry accumulator so the whole city renders in a handful of draw calls
  function GeoBuilder() {
    this.pos = []; this.nrm = []; this.uv = []; this.idx = [];
  }
  GeoBuilder.prototype.vert = function (x, y, z, nx, ny, nz, u, v) {
    this.pos.push(x, y, z); this.nrm.push(nx, ny, nz); this.uv.push(u, v);
    return this.pos.length / 3 - 1;
  };
  GeoBuilder.prototype.quad = function (a, b, c, d) { this.idx.push(a, b, c, a, c, d); };
  GeoBuilder.prototype.build = function () {
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(this.pos, 3));
    g.setAttribute('normal', new THREE.Float32BufferAttribute(this.nrm, 3));
    g.setAttribute('uv', new THREE.Float32BufferAttribute(this.uv, 2));
    g.setIndex(this.idx);
    g.computeBoundingSphere();
    return g;
  };

  // ---------- Procedural facade textures (night city) ----------
  // One tile = 4 window columns x 4 floors  ->  16 m wide x 14 m tall
  const TILE_W = 16, TILE_H = 14;

  function makeFacade(style, seed) {
    const c = document.createElement('canvas');
    c.width = 256; c.height = 256;
    const e = document.createElement('canvas');
    e.width = 256; e.height = 256;
    const ctx = c.getContext('2d');
    const ectx = e.getContext('2d');
    ectx.fillStyle = '#000';
    ectx.fillRect(0, 0, 256, 256);

    const S = {
      glass:  { base: '#1d3346', frame: '#2c4a63', win: '#24445e', lit: ['#bfe3ff', '#ffe7b0', '#9fd2ff'], litP: 0.45, full: true },
      office: { base: '#4a4f58', frame: '#5d636e', win: '#1c222c', lit: ['#ffe2a8', '#fff3d6', '#cfe6ff'], litP: 0.35, full: false },
      brick:  { base: '#6b3328', frame: '#7d4033', win: '#1a1512', lit: ['#ffc977', '#ffdca0'], litP: 0.4, full: false },
      dark:   { base: '#14171d', frame: '#20252e', win: '#0d1016', lit: ['#8fd3ff', '#ffffff', '#ffd08a'], litP: 0.22, full: true },
      stone:  { base: '#8f8572', frame: '#a39881', win: '#211c16', lit: ['#ffd590', '#ffe8bf'], litP: 0.55, full: false },
      concrete: { base: '#5e5f60', frame: '#6c6d6f', win: '#24272b', lit: ['#e8f1ff'], litP: 0.15, full: false }
    }[style];

    ctx.fillStyle = S.base;
    ctx.fillRect(0, 0, 256, 256);

    // Brick / stone texture noise
    if (style === 'brick' || style === 'stone') {
      for (let y = 0; y < 256; y += 6) {
        for (let x = (y / 6) % 2 ? 0 : 6; x < 256; x += 12) {
          ctx.fillStyle = `rgba(0,0,0,${0.05 + hash(seed + x * 3 + y) * 0.12})`;
          ctx.fillRect(x, y, 11, 5);
        }
      }
    }

    for (let fy = 0; fy < 4; fy++) {
      // floor slab line
      ctx.fillStyle = S.frame;
      ctx.fillRect(0, fy * 64, 256, 6);
      for (let fx = 0; fx < 4; fx++) {
        const x = fx * 64 + (S.full ? 3 : 12);
        const y = fy * 64 + (S.full ? 9 : 16);
        const w = S.full ? 58 : 40;
        const h = S.full ? 52 : 36;
        const r = hash(seed * 13.7 + fy * 7.1 + fx * 3.3);
        if (r < S.litP) {
          const col = S.lit[Math.floor(hash(r * 91) * S.lit.length)];
          ctx.fillStyle = col;
          ctx.fillRect(x, y, w, h);
          ectx.fillStyle = col;
          ectx.globalAlpha = 0.55 + hash(r * 17) * 0.45;
          ectx.fillRect(x, y, w, h);
          ectx.globalAlpha = 1;
          // blinds
          ctx.fillStyle = 'rgba(0,0,0,0.18)';
          for (let b = y + 4; b < y + h; b += 7) ctx.fillRect(x, b, w, 1);
        } else {
          const g = ctx.createLinearGradient(x, y, x + w, y + h);
          g.addColorStop(0, S.win);
          g.addColorStop(1, '#05070a');
          ctx.fillStyle = g;
          ctx.fillRect(x, y, w, h);
        }
        if (S.full) {
          ctx.fillStyle = S.frame;
          ctx.fillRect(fx * 64, fy * 64, 3, 64);
        }
      }
    }

    const tex = new THREE.CanvasTexture(c);
    const etex = new THREE.CanvasTexture(e);
    [tex, etex].forEach(t => {
      t.wrapS = t.wrapT = THREE.RepeatWrapping;
      t.anisotropy = 4;
    });
    return new THREE.MeshLambertMaterial({
      map: tex,
      emissive: 0xffffff,
      emissiveMap: etex,
      emissiveIntensity: 0.9,
      side: THREE.DoubleSide
    });
  }

  function makeGroundTexture(kind) {
    const c = document.createElement('canvas');
    c.width = 128; c.height = 128;
    const ctx = c.getContext('2d');
    if (kind === 'sidewalk') {
      ctx.fillStyle = '#4a4c50';
      ctx.fillRect(0, 0, 128, 128);
      ctx.strokeStyle = '#3a3c40';
      ctx.lineWidth = 2;
      for (let i = 0; i <= 128; i += 32) {
        ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i, 128); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(0, i); ctx.lineTo(128, i); ctx.stroke();
      }
      for (let i = 0; i < 300; i++) {
        ctx.fillStyle = `rgba(255,255,255,${hash(i) * 0.05})`;
        ctx.fillRect(hash(i * 3) * 128, hash(i * 7) * 128, 2, 2);
      }
    } else if (kind === 'asphalt') {
      ctx.fillStyle = '#1e2024';
      ctx.fillRect(0, 0, 128, 128);
      for (let i = 0; i < 900; i++) {
        const v = 20 + Math.floor(hash(i * 1.7) * 30);
        ctx.fillStyle = `rgb(${v},${v},${v + 3})`;
        ctx.fillRect(hash(i * 3.1) * 128, hash(i * 5.3) * 128, 2, 2);
      }
    } else if (kind === 'gravel') {
      ctx.fillStyle = '#3b342c';
      ctx.fillRect(0, 0, 128, 128);
      for (let i = 0; i < 1200; i++) {
        const v = 40 + Math.floor(hash(i * 2.3) * 50);
        ctx.fillStyle = `rgb(${v},${v - 6},${v - 12})`;
        ctx.fillRect(hash(i * 4.1) * 128, hash(i * 6.7) * 128, 2, 2);
      }
    }
    const t = new THREE.CanvasTexture(c);
    t.wrapS = t.wrapT = THREE.RepeatWrapping;
    t.anisotropy = 4;
    return t;
  }

  function makeSkyTexture() {
    const c = document.createElement('canvas');
    c.width = 4; c.height = 512;
    const ctx = c.getContext('2d');
    const g = ctx.createLinearGradient(0, 0, 0, 512);
    g.addColorStop(0.0, '#03040a');
    g.addColorStop(0.35, '#0b0f24');
    g.addColorStop(0.47, '#2a1d3d');
    g.addColorStop(0.5, '#5a3448');   // city glow on horizon
    g.addColorStop(0.53, '#1a1424');
    g.addColorStop(1.0, '#07070b');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, 4, 512);
    return new THREE.CanvasTexture(c);
  }

  function makeLabelTexture(lines, opts) {
    opts = opts || {};
    const c = document.createElement('canvas');
    c.width = opts.w || 512; c.height = opts.h || 128;
    const ctx = c.getContext('2d');
    ctx.fillStyle = opts.bg || '#123a7a';
    ctx.fillRect(0, 0, c.width, c.height);
    if (opts.border !== false) {
      ctx.strokeStyle = opts.borderColor || '#ffffff';
      ctx.lineWidth = 6;
      ctx.strokeRect(6, 6, c.width - 12, c.height - 12);
    }
    ctx.fillStyle = opts.fg || '#ffffff';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    if (lines.length === 1) {
      ctx.font = `bold ${opts.size || 64}px "Chakra Petch", Arial, sans-serif`;
      ctx.fillText(lines[0], c.width / 2, c.height / 2 + 4);
    } else {
      ctx.font = `bold ${Math.round((opts.size || 64) * 0.4)}px Arial, sans-serif`;
      ctx.fillText(lines[0], c.width / 2, c.height * 0.27);
      ctx.font = `bold ${opts.size || 64}px "Chakra Petch", Arial, sans-serif`;
      ctx.fillText(lines[1], c.width / 2, c.height * 0.65);
    }
    const t = new THREE.CanvasTexture(c);
    t.anisotropy = 4;
    return t;
  }

  // ==========================================================================
  // MAIN BUILDER
  // ==========================================================================
  function buildTorontoCity(scene) {
    const MAP = window.TORONTO_MAP;
    if (!MAP) throw new Error('TORONTO_MAP data missing (toronto_map.js not loaded)');

    const [[minX, minZ], [maxX, maxZ]] = MAP.bounds;
    const PLAY = { minX: minX + 25, maxX: maxX - 25, minZ: minZ + 25, maxZ: maxZ - 25 };
    const LM = MAP.landmarks;

    // ---------- Collision spatial grid ----------
    const CELL = 24;
    const grid = new Map();
    const solids = []; // {type:'poly', pts, bb:[x0,z0,x1,z1]} | {type:'circle', x, z, r, bb}
    function cellKey(cx, cz) { return cx * 73856093 ^ cz * 19349663; }
    function addSolid(s) {
      solids.push(s);
      const [x0, z0, x1, z1] = s.bb;
      for (let cx = Math.floor(x0 / CELL); cx <= Math.floor(x1 / CELL); cx++) {
        for (let cz = Math.floor(z0 / CELL); cz <= Math.floor(z1 / CELL); cz++) {
          const k = cellKey(cx, cz);
          if (!grid.has(k)) grid.set(k, []);
          grid.get(k).push(s);
        }
      }
    }
    function addCircle(x, z, r) {
      addSolid({ type: 'circle', x, z, r, bb: [x - r, z - r, x + r, z + r] });
    }

    function canMoveTo(x, z, radius) {
      const r = radius || 0.6;
      if (x < PLAY.minX || x > PLAY.maxX || z < PLAY.minZ || z > PLAY.maxZ) return false;
      const seen = new Set();
      for (let cx = Math.floor((x - r) / CELL); cx <= Math.floor((x + r) / CELL); cx++) {
        for (let cz = Math.floor((z - r) / CELL); cz <= Math.floor((z + r) / CELL); cz++) {
          const list = grid.get(cellKey(cx, cz));
          if (!list) continue;
          for (let i = 0; i < list.length; i++) {
            const s = list[i];
            if (seen.has(s)) continue;
            seen.add(s);
            const bb = s.bb;
            if (x + r < bb[0] || x - r > bb[2] || z + r < bb[1] || z - r > bb[3]) continue;
            if (s.type === 'circle') {
              const dx = x - s.x, dz = z - s.z;
              if (dx * dx + dz * dz < (s.r + r) * (s.r + r)) return false;
            } else {
              if (pointInPoly(x, z, s.pts)) return false;
              const p = s.pts, r2 = r * r;
              for (let a = 0, b = p.length - 1; a < p.length; b = a++) {
                if (distToSegSq(x, z, p[b][0], p[b][1], p[a][0], p[a][1]) < r2) return false;
              }
            }
          }
        }
      }
      return true;
    }

    function findOpenSpot(cx, cz, minR, maxR, radius) {
      for (let i = 0; i < 400; i++) {
        const a = Math.random() * Math.PI * 2;
        const d = minR + Math.random() * (maxR - minR);
        const x = cx + Math.cos(a) * d, z = cz + Math.sin(a) * d;
        if (canMoveTo(x, z, radius || 1.6)) return { x, z };
      }
      // widen search
      for (let d = 2; d < 200; d += 2) {
        for (let k = 0; k < 16; k++) {
          const a = (k / 16) * Math.PI * 2;
          const x = cx + Math.cos(a) * d, z = cz + Math.sin(a) * d;
          if (canMoveTo(x, z, radius || 1.6)) return { x, z };
        }
      }
      return { x: cx, z: cz };
    }

    // ---------- Sky, fog, lighting ----------
    scene.background = new THREE.Color(0x07070b);
    scene.fog = new THREE.FogExp2(0x1a1424, 0.0024);

    const sky = new THREE.Mesh(
      new THREE.SphereGeometry(2200, 32, 16),
      new THREE.MeshBasicMaterial({ map: makeSkyTexture(), side: THREE.BackSide, fog: false, depthWrite: false })
    );
    sky.renderOrder = -10;
    scene.add(sky);

    // Stars
    const starPos = [];
    for (let i = 0; i < 1400; i++) {
      const th = hash(i * 1.3) * Math.PI * 2;
      const ph = Math.acos(1 - hash(i * 2.7) * 0.9); // upper hemisphere only
      starPos.push(2000 * Math.sin(ph) * Math.cos(th), 2000 * Math.cos(ph) + 80, 2000 * Math.sin(ph) * Math.sin(th));
    }
    const starGeo = new THREE.BufferGeometry();
    starGeo.setAttribute('position', new THREE.Float32BufferAttribute(starPos, 3));
    const stars = new THREE.Points(starGeo, new THREE.PointsMaterial({ color: 0xcfd8ff, size: 2.2, sizeAttenuation: false, fog: false, transparent: true, opacity: 0.8 }));
    scene.add(stars);

    scene.add(new THREE.HemisphereLight(0x5a6a9a, 0x2a2018, 0.85));
    scene.add(new THREE.AmbientLight(0x3a4050, 0.55));
    const moon = new THREE.DirectionalLight(0x9fb0e0, 0.55);
    moon.position.set(-300, 600, -200);
    scene.add(moon);

    // ---------- Ground: sidewalks / plazas ----------
    const sideTex = makeGroundTexture('sidewalk');
    const W = (maxX - minX) + 1600, D = (maxZ - minZ) + 1600;
    sideTex.repeat.set(W / 4, D / 4);
    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(W, D),
      new THREE.MeshLambertMaterial({ map: sideTex })
    );
    ground.rotation.x = -Math.PI / 2;
    ground.position.set((minX + maxX) / 2, 0, (minZ + maxZ) / 2);
    scene.add(ground);

    // Lake Ontario beyond the southern edge of the data
    const lake = new THREE.Mesh(
      new THREE.PlaneGeometry(6000, 3000),
      new THREE.MeshPhongMaterial({ color: 0x0a1424, specular: 0x334466, shininess: 80 })
    );
    lake.rotation.x = -Math.PI / 2;
    lake.position.set(0, 0.02, maxZ + 1560);
    scene.add(lake);

    // ---------- Roads ----------
    const asphaltTex = makeGroundTexture('asphalt');
    const roadGB = new GeoBuilder();
    const lineGB = new GeoBuilder();
    const deckGB = new GeoBuilder();
    const lampSpots = [];
    const signCandidates = [];
    const MAJOR = { primary: 1, secondary: 1, tertiary: 1, trunk: 1, motorway: 1 };
    const LEVEL_Y = { motorway: 1, motorway_link: 1, trunk: 1, trunk_link: 1 };
    const pillarSpots = [];

    function ribbon(gb, pts, width, y, uScale) {
      let dist = 0;
      for (let i = 0; i < pts.length - 1; i++) {
        const [ax, az] = pts[i], [bx, bz] = pts[i + 1];
        const dx = bx - ax, dz = bz - az;
        const len = Math.hypot(dx, dz);
        if (len < 0.01) continue;
        const nx = -dz / len * width / 2, nz = dx / len * width / 2;
        const u0 = dist / uScale, u1 = (dist + len) / uScale;
        const a = gb.vert(ax + nx, y, az + nz, 0, 1, 0, 0, u0);
        const b = gb.vert(ax - nx, y, az - nz, 0, 1, 0, width / uScale, u0);
        const c = gb.vert(bx - nx, y, bz - nz, 0, 1, 0, width / uScale, u1);
        const d = gb.vert(bx + nx, y, bz + nz, 0, 1, 0, 0, u1);
        gb.quad(a, b, c, d);
        // round the joint with an extra square cap so bends don't show gaps
        dist += len;
      }
    }

    function wallStrip(gb, pts, offset, y0, y1) {
      for (let i = 0; i < pts.length - 1; i++) {
        const [ax, az] = pts[i], [bx, bz] = pts[i + 1];
        const dx = bx - ax, dz = bz - az;
        const len = Math.hypot(dx, dz);
        if (len < 0.01) continue;
        const nx = -dz / len, nz = dx / len;
        const ox = nx * offset, oz = nz * offset;
        const a = gb.vert(ax + ox, y0, az + oz, nx, 0, nz, 0, 0);
        const b = gb.vert(bx + ox, y0, bz + oz, nx, 0, nz, len / 8, 0);
        const c = gb.vert(bx + ox, y1, bz + oz, nx, 0, nz, len / 8, 1);
        const d = gb.vert(ax + ox, y1, az + oz, nx, 0, nz, 0, 1);
        gb.quad(a, b, c, d);
      }
    }

    MAP.roads.forEach((r, ri) => {
      const pts = toPairs(r.p);
      if (pts.length < 2) return;
      const elevated = r.l && LEVEL_Y[r.t];
      if (elevated) {
        const y = 5 + r.l * 3.5;
        ribbon(deckGB, pts, r.w + 2, y, 8);
        ribbon(deckGB, pts, r.w + 2, y - 1.4, 8);
        wallStrip(deckGB, pts, (r.w + 2) / 2, y - 1.4, y + 1.1);
        wallStrip(deckGB, pts, -(r.w + 2) / 2, y - 1.4, y + 1.1);
        // pillars every ~28 m
        let carry = 0;
        for (let i = 0; i < pts.length - 1; i++) {
          const [ax, az] = pts[i], [bx, bz] = pts[i + 1];
          const len = Math.hypot(bx - ax, bz - az);
          let t = carry;
          while (t < len) {
            const f = t / len;
            pillarSpots.push({ x: ax + (bx - ax) * f, z: az + (bz - az) * f, h: y - 1.4 });
            t += 28;
          }
          carry = t - len;
        }
        return;
      }
      const y = MAJOR[r.t] ? 0.05 : (r.t === 'service' ? 0.03 : 0.04);
      ribbon(roadGB, pts, r.w, y, 8);

      if (MAJOR[r.t]) {
        // double yellow centre line
        ribbon(lineGB, pts.map(p => p), 0.16, y + 0.01, 4);
        // lamps alternating sides every 32 m
        let carry = 10, side = 1;
        for (let i = 0; i < pts.length - 1; i++) {
          const [ax, az] = pts[i], [bx, bz] = pts[i + 1];
          const dx = bx - ax, dz = bz - az;
          const len = Math.hypot(dx, dz);
          if (len < 0.01) continue;
          const nx = -dz / len, nz = dx / len;
          let t = carry;
          while (t < len) {
            const f = t / len;
            const off = r.w / 2 + 1.2;
            lampSpots.push({
              x: ax + dx * f + nx * off * side,
              z: az + dz * f + nz * off * side,
              ang: Math.atan2(-nx * side, -nz * side)
            });
            side *= -1;
            t += 32;
          }
          carry = t - len;
        }
        if (r.n) {
          // longest segment midpoint for street sign
          let best = null, bestLen = 0;
          for (let i = 0; i < pts.length - 1; i++) {
            const len = Math.hypot(pts[i + 1][0] - pts[i][0], pts[i + 1][1] - pts[i][1]);
            if (len > bestLen) { bestLen = len; best = i; }
          }
          if (best !== null && bestLen > 25) {
            const [ax, az] = pts[best], [bx, bz] = pts[best + 1];
            const dx = (bx - ax) / bestLen, dz = (bz - az) / bestLen;
            signCandidates.push({
              name: r.n,
              x: (ax + bx) / 2 + (-dz) * (r.w / 2 + 2),
              z: (az + bz) / 2 + dx * (r.w / 2 + 2),
              ang: Math.atan2(dx, dz)
            });
          }
        }
      }
    });

    const roadMesh = new THREE.Mesh(roadGB.build(), new THREE.MeshLambertMaterial({ map: asphaltTex }));
    scene.add(roadMesh);
    const lineMesh = new THREE.Mesh(lineGB.build(), new THREE.MeshBasicMaterial({ color: 0xd9a514 }));
    scene.add(lineMesh);
    const concreteMat = new THREE.MeshLambertMaterial({ color: 0x55575c, side: THREE.DoubleSide });
    if (deckGB.pos.length) scene.add(new THREE.Mesh(deckGB.build(), concreteMat));

    // Gardiner pillars (instanced)
    if (pillarSpots.length) {
      const pGeo = new THREE.CylinderGeometry(0.9, 1.1, 1, 10);
      pGeo.translate(0, 0.5, 0);
      const pillars = new THREE.InstancedMesh(pGeo, concreteMat, pillarSpots.length);
      const m = new THREE.Matrix4();
      pillarSpots.forEach((p, i) => {
        m.makeScale(1, p.h, 1);
        m.setPosition(p.x, 0, p.z);
        pillars.setMatrixAt(i, m);
        addCircle(p.x, p.z, 1.1);
      });
      scene.add(pillars);
    }

    // ---------- Rail corridor ----------
    const gravelTex = makeGroundTexture('gravel');
    const railBedGB = new GeoBuilder();
    const railGB = new GeoBuilder();
    MAP.rails.forEach(r => {
      const pts = toPairs(r.p);
      if (pts.length < 2) return;
      ribbon(railBedGB, pts, 3.6, 0.035, 4);
      // two steel rails
      const left = [], right = [];
      for (let i = 0; i < pts.length; i++) {
        const a = pts[Math.max(0, i - 1)], b = pts[Math.min(pts.length - 1, i + 1)];
        const dx = b[0] - a[0], dz = b[1] - a[1];
        const len = Math.hypot(dx, dz) || 1;
        const nx = -dz / len * 0.72, nz = dx / len * 0.72;
        left.push([pts[i][0] + nx, pts[i][1] + nz]);
        right.push([pts[i][0] - nx, pts[i][1] - nz]);
      }
      ribbon(railGB, left, 0.12, 0.13, 4);
      ribbon(railGB, right, 0.12, 0.13, 4);
    });
    if (railBedGB.pos.length) {
      scene.add(new THREE.Mesh(railBedGB.build(), new THREE.MeshLambertMaterial({ map: gravelTex })));
      scene.add(new THREE.Mesh(railGB.build(), new THREE.MeshPhongMaterial({ color: 0x8a8f99, shininess: 90, specular: 0x999999 })));
    }

    // ---------- Buildings ----------
    const STYLES = ['glass', 'office', 'brick', 'dark', 'stone', 'concrete'];
    const facadeMats = {};
    const facadeGB = {};
    STYLES.forEach((s, i) => { facadeMats[s] = makeFacade(s, i * 17 + 3); facadeGB[s] = new GeoBuilder(); });
    const roofGB = new GeoBuilder();
    const roofLights = [];
    let unionPoly = null, rogersPoly = null;

    function addBuilding(pts, h, style, minY) {
      const y0 = minY || 0;
      const gb = facadeGB[style];
      let u = 0;
      for (let i = 0; i < pts.length; i++) {
        const [ax, az] = pts[i], [bx, bz] = pts[(i + 1) % pts.length];
        const dx = bx - ax, dz = bz - az;
        const len = Math.hypot(dx, dz);
        if (len < 0.01) continue;
        const nx = dz / len, nz = -dx / len; // outward for CCW (positive area)
        const u0 = u / TILE_W, u1 = (u + len) / TILE_W;
        const v0 = y0 / TILE_H, v1 = h / TILE_H;
        const a = gb.vert(ax, y0, az, nx, 0, nz, u0, v0);
        const b = gb.vert(bx, y0, bz, nx, 0, nz, u1, v0);
        const c = gb.vert(bx, h, bz, nx, 0, nz, u1, v1);
        const d = gb.vert(ax, h, az, nx, 0, nz, u0, v1);
        gb.quad(a, b, c, d);
        u += len;
      }
      // roof
      try {
        const contour = pts.map(p => new THREE.Vector2(p[0], p[1]));
        const tris = THREE.ShapeUtils.triangulateShape(contour, []);
        const base = roofGB.pos.length / 3;
        pts.forEach(p => roofGB.vert(p[0], h, p[1], 0, 1, 0, p[0] / 10, p[1] / 10));
        tris.forEach(t => roofGB.idx.push(base + t[0], base + t[1], base + t[2]));
      } catch (e) { /* skip degenerate roof */ }
    }

    MAP.buildings.forEach((b, bi) => {
      let pts = toPairs(b.p);
      if (pts.length < 3) return;
      if (polyArea(pts) < 0) pts = pts.reverse();
      const area = polyArea(pts);
      if (area < 6) return;
      const [cx, cz] = centroid(pts);
      const name = b.n || '';

      // CN Tower gets a hand-built model
      if (Math.hypot(cx - LM.cnTower[0], cz - LM.cnTower[1]) < 40 && (name.indexOf('CN Tower') === 0 || (b.h && b.h > 300))) return;
      if (name === 'CN Tower tickets') return;

      let h = b.h;
      if (!h) {
        // unknown height: plausible downtown default scaled by footprint
        h = 9 + hash(bi * 1.37) * (area > 2000 ? 40 : 18);
      }
      if (name === 'Union Station') h = 26;
      h = Math.max(4, Math.min(h, 320));

      let style;
      if (name === 'Union Station' || name.indexOf('Royal York') >= 0 || name.indexOf('Dominion Public') >= 0 || name.indexOf('Hockey Hall') >= 0) style = 'stone';
      else if (name.indexOf('Rogers Centre') === 0) style = 'concrete';
      else if (h > 90) style = hash(bi) > 0.45 ? 'glass' : 'dark';
      else if (h > 40) style = ['glass', 'office', 'dark'][Math.floor(hash(bi * 3.3) * 3)];
      else style = ['brick', 'office', 'brick', 'concrete'][Math.floor(hash(bi * 5.1) * 4)];

      if (name.indexOf('Rogers Centre') === 0) {
        rogersPoly = { pts, cx, cz };
        h = 32; // walls; dome added separately
      }
      if (name === 'Union Station') unionPoly = { pts, cx, cz, h };

      addBuilding(pts, h, style);

      let x0 = Infinity, z0 = Infinity, x1 = -Infinity, z1 = -Infinity;
      pts.forEach(p => { x0 = Math.min(x0, p[0]); z0 = Math.min(z0, p[1]); x1 = Math.max(x1, p[0]); z1 = Math.max(z1, p[1]); });
      addSolid({ type: 'poly', pts, bb: [x0, z0, x1, z1], h, name });

      if (h > 70 && roofLights.length < 60) roofLights.push(new THREE.Vector3(cx, h + 1.5, cz));
    });

    STYLES.forEach(s => {
      if (facadeGB[s].pos.length) scene.add(new THREE.Mesh(facadeGB[s].build(), facadeMats[s]));
    });
    scene.add(new THREE.Mesh(roofGB.build(), new THREE.MeshLambertMaterial({ color: 0x1f2126, side: THREE.DoubleSide })));

    // Blinking red aircraft-warning lights on tall rooftops
    const warnMat = new THREE.MeshBasicMaterial({ color: 0xff2020, fog: false });
    const warnGeo = new THREE.SphereGeometry(0.9, 8, 6);
    const warnLights = new THREE.InstancedMesh(warnGeo, warnMat, Math.max(1, roofLights.length + 6));
    const tmpM = new THREE.Matrix4();
    roofLights.forEach((p, i) => { tmpM.makeTranslation(p.x, p.y, p.z); warnLights.setMatrixAt(i, tmpM); });
    warnLights.count = roofLights.length;
    scene.add(warnLights);

    // ---------- Rogers Centre dome ----------
    {
      let cx = LM.rogersCentre[0], cz = LM.rogersCentre[1], R = 105;
      if (rogersPoly) {
        cx = rogersPoly.cx; cz = rogersPoly.cz;
        R = rogersPoly.pts.reduce((s, p) => s + Math.hypot(p[0] - cx, p[1] - cz), 0) / rogersPoly.pts.length;
      } else {
        const ring = [];
        for (let i = 0; i < 40; i++) ring.push([cx + Math.cos(-i / 40 * Math.PI * 2) * R, cz + Math.sin(-i / 40 * Math.PI * 2) * R]);
        addBuilding(ring, 32, 'concrete');
        addSolid({ type: 'poly', pts: ring, bb: [cx - R, cz - R, cx + R, cz + R], h: 32 });
      }
      const dome = new THREE.Mesh(
        new THREE.SphereGeometry(R * 0.96, 48, 16, 0, Math.PI * 2, 0, Math.PI / 2),
        new THREE.MeshPhongMaterial({ color: 0x9aa3ad, specular: 0x445566, shininess: 30 })
      );
      dome.scale.set(1, 50 / R, 1);
      dome.position.set(cx, 32, cz);
      scene.add(dome);
      // panel ribs
      const ribMat = new THREE.MeshBasicMaterial({ color: 0x3b4048 });
      for (let i = 0; i < 4; i++) {
        const rib = new THREE.Mesh(new THREE.TorusGeometry(R * 0.96 * (1 - i * 0.22), 0.6, 4, 64), ribMat);
        rib.rotation.x = Math.PI / 2;
        rib.position.set(cx, 32 + 50 * Math.sqrt(1 - Math.pow(1 - i * 0.22, 2)), cz);
        scene.add(rib);
      }
    }

    // ---------- CN Tower (hand-modelled, 553 m) ----------
    const tower = new THREE.Group();
    tower.position.set(LM.cnTower[0], 0, LM.cnTower[1]);
    const towerMat = new THREE.MeshLambertMaterial({ color: 0xb9b4aa, emissive: 0xff2244, emissiveIntensity: 0.18, fog: false });
    const podMat = new THREE.MeshLambertMaterial({ color: 0x8c8a86, fog: false });
    const glowMat = new THREE.MeshBasicMaterial({ color: 0xfff1cc, fog: false });

    // Central hexagonal shaft
    const shaft = new THREE.Mesh(new THREE.CylinderGeometry(4.8, 8, 340, 6), towerMat);
    shaft.position.y = 170;
    tower.add(shaft);
    // Three Y-legs
    for (let i = 0; i < 3; i++) {
      const a = i * Math.PI * 2 / 3;
      const leg = new THREE.Mesh(new THREE.CylinderGeometry(1.2, 6.5, 300, 4), towerMat);
      leg.position.set(Math.cos(a) * 9, 150, Math.sin(a) * 9);
      leg.rotation.y = -a;
      leg.rotation.z = Math.cos(a) * -0.018;
      leg.rotation.x = Math.sin(a) * 0.018;
      tower.add(leg);
      addCircle(LM.cnTower[0] + Math.cos(a) * 12, LM.cnTower[1] + Math.sin(a) * 12, 6);
    }
    addCircle(LM.cnTower[0], LM.cnTower[1], 9);
    // Main pod
    const podLower = new THREE.Mesh(new THREE.CylinderGeometry(22, 7, 14, 32), podMat);
    podLower.position.y = 333; tower.add(podLower);
    const podBand = new THREE.Mesh(new THREE.CylinderGeometry(22.5, 22.5, 10, 32), glowMat);
    podBand.position.y = 345; tower.add(podBand);
    const podMid = new THREE.Mesh(new THREE.CylinderGeometry(21, 22.5, 6, 32), podMat);
    podMid.position.y = 353; tower.add(podMid);
    const podTop = new THREE.Mesh(new THREE.CylinderGeometry(9, 21, 10, 32), podMat);
    podTop.position.y = 361; tower.add(podTop);
    // Upper shaft + SkyPod
    const upper = new THREE.Mesh(new THREE.CylinderGeometry(3.2, 4.4, 92, 12), towerMat);
    upper.position.y = 412; tower.add(upper);
    const skyPod = new THREE.Mesh(new THREE.CylinderGeometry(6.5, 6.5, 7, 20), glowMat);
    skyPod.position.y = 447; tower.add(skyPod);
    // Antenna
    const ant = new THREE.Mesh(new THREE.CylinderGeometry(0.7, 2.8, 95, 8), podMat);
    ant.position.y = 505; tower.add(ant);
    scene.add(tower);

    // Tower warning lights get their own instance slots
    const towerLightYs = [553, 520, 470, 365, 300];
    towerLightYs.forEach((y, i) => {
      tmpM.makeTranslation(LM.cnTower[0], y, LM.cnTower[1] + (i ? 4 : 0));
      warnLights.setMatrixAt(roofLights.length + i, tmpM);
    });
    warnLights.count = roofLights.length + towerLightYs.length;
    warnLights.instanceMatrix.needsUpdate = true;

    // ---------- CN Tower Peace Sanctuary Zone (NO FIGHTING ZONE) ----------
    const peaceCenter = [LM.cnTower[0], LM.cnTower[1]];
    const PEACE_RADIUS = 55;

    // Glowing Sanctuary Floor Disc
    const peaceCanvas = document.createElement('canvas');
    peaceCanvas.width = 512; peaceCanvas.height = 512;
    const pctx = peaceCanvas.getContext('2d');
    pctx.fillStyle = '#06281c';
    pctx.beginPath(); pctx.arc(256, 256, 250, 0, Math.PI * 2); pctx.fill();

    // Concentric sanctuary rings
    pctx.lineWidth = 10;
    pctx.strokeStyle = '#10b981';
    pctx.beginPath(); pctx.arc(256, 256, 240, 0, Math.PI * 2); pctx.stroke();
    pctx.lineWidth = 5;
    pctx.strokeStyle = '#34d399';
    pctx.beginPath(); pctx.arc(256, 256, 210, 0, Math.PI * 2); pctx.stroke();
    pctx.strokeStyle = 'rgba(52, 211, 153, 0.45)';
    pctx.beginPath(); pctx.arc(256, 256, 140, 0, Math.PI * 2); pctx.stroke();

    // Giant glowing Peace Symbol in the center
    pctx.strokeStyle = '#6ee7b7';
    pctx.lineWidth = 18;
    pctx.beginPath();
    pctx.arc(256, 256, 90, 0, Math.PI * 2);
    pctx.moveTo(256, 166); pctx.lineTo(256, 346); // vertical
    pctx.moveTo(256, 256); pctx.lineTo(192, 320); // branch left
    pctx.moveTo(256, 256); pctx.lineTo(320, 320); // branch right
    pctx.stroke();

    // Text around border
    pctx.font = 'bold 22px "Chakra Petch", Arial, sans-serif';
    pctx.fillStyle = '#a7f3d0';
    pctx.textAlign = 'center';
    pctx.fillText('☮ CN TOWER PEACE SANCTUARY — NO COMBAT ZONE ☮', 256, 490);
    pctx.fillText('SAFE HAVEN • REST & RECOVER VITALITY', 256, 35);

    const peaceTex = new THREE.CanvasTexture(peaceCanvas);
    peaceTex.anisotropy = 4;
    const peaceFloor = new THREE.Mesh(
      new THREE.CircleGeometry(PEACE_RADIUS, 48),
      new THREE.MeshLambertMaterial({ map: peaceTex, transparent: true, opacity: 0.95 })
    );
    peaceFloor.rotation.x = -Math.PI / 2;
    peaceFloor.position.set(peaceCenter[0], 0.08, peaceCenter[1]);
    scene.add(peaceFloor);

    // Glowing Translucent Sanctuary Boundary Ring Wall
    const barrierGeo = new THREE.CylinderGeometry(PEACE_RADIUS, PEACE_RADIUS, 3.8, 48, 1, true);
    const barrierMat = new THREE.MeshBasicMaterial({
      color: 0x10b981,
      transparent: true,
      opacity: 0.28,
      side: THREE.DoubleSide
    });
    const barrierMesh = new THREE.Mesh(barrierGeo, barrierMat);
    barrierMesh.position.set(peaceCenter[0], 1.9, peaceCenter[1]);
    scene.add(barrierMesh);

    // Neon edge ring at top and bottom of barrier
    const rimGeo = new THREE.TorusGeometry(PEACE_RADIUS, 0.28, 6, 48);
    const rimMat = new THREE.MeshBasicMaterial({ color: 0x34d399 });
    const topRim = new THREE.Mesh(rimGeo, rimMat);
    topRim.rotation.x = Math.PI / 2;
    topRim.position.set(peaceCenter[0], 3.8, peaceCenter[1]);
    scene.add(topRim);
    const bottomRim = new THREE.Mesh(rimGeo, rimMat);
    bottomRim.rotation.x = Math.PI / 2;
    bottomRim.position.set(peaceCenter[0], 0.12, peaceCenter[1]);
    scene.add(bottomRim);

    // 4 Sanctuary Entrance Gate Arches (North, South, East, West)
    const gateDirections = [
      { angle: 0, nx: 0, nz: -1, label: 'NORTH ENTRANCE' },
      { angle: Math.PI, nx: 0, nz: 1, label: 'SOUTH ENTRANCE' },
      { angle: Math.PI / 2, nx: 1, nz: 0, label: 'EAST ENTRANCE' },
      { angle: -Math.PI / 2, nx: -1, nz: 0, label: 'WEST ENTRANCE' }
    ];
    gateDirections.forEach(g => {
      const gx = peaceCenter[0] + g.nx * PEACE_RADIUS;
      const gz = peaceCenter[1] + g.nz * PEACE_RADIUS;
      const gateGroup = new THREE.Group();
      gateGroup.position.set(gx, 0, gz);
      gateGroup.rotation.y = -g.angle;

      // Pillars
      const pillarMat = new THREE.MeshLambertMaterial({ color: 0x064e3b });
      const p1 = new THREE.Mesh(new THREE.CylinderGeometry(0.35, 0.45, 5.8, 8), pillarMat);
      p1.position.set(-3.5, 2.9, 0); gateGroup.add(p1);
      const p2 = new THREE.Mesh(new THREE.CylinderGeometry(0.35, 0.45, 5.8, 8), pillarMat);
      p2.position.set(3.5, 2.9, 0); gateGroup.add(p2);

      // Glowing Arch Banner
      const archSign = new THREE.Mesh(
        new THREE.BoxGeometry(8.2, 1.3, 0.3),
        new THREE.MeshBasicMaterial({
          map: makeLabelTexture(['☮ PEACE SANCTUARY ☮', 'NO COMBAT PERMITTED'], {
            bg: '#064e3b', fg: '#6ee7b7', borderColor: '#34d399', size: 48, w: 512, h: 128
          })
        })
      );
      archSign.position.set(0, 5.5, 0);
      gateGroup.add(archSign);

      scene.add(gateGroup);
    });

    // Floating 3D Peace Symbol in the Plaza
    const peaceIconGroup = new THREE.Group();
    peaceIconGroup.position.set(peaceCenter[0], 6.5, peaceCenter[1]);
    const pRingMesh = new THREE.Mesh(new THREE.TorusGeometry(2.4, 0.28, 8, 32), new THREE.MeshBasicMaterial({ color: 0x34d399 }));
    peaceIconGroup.add(pRingMesh);
    const pvBar = new THREE.Mesh(new THREE.CylinderGeometry(0.24, 0.24, 4.8, 8), new THREE.MeshBasicMaterial({ color: 0x34d399 }));
    peaceIconGroup.add(pvBar);
    const plArm = new THREE.Mesh(new THREE.CylinderGeometry(0.2, 0.2, 2.4, 8), new THREE.MeshBasicMaterial({ color: 0x34d399 }));
    plArm.rotation.z = Math.PI / 4;
    plArm.position.set(-0.85, -0.85, 0);
    peaceIconGroup.add(plArm);
    const prArm = new THREE.Mesh(new THREE.CylinderGeometry(0.2, 0.2, 2.4, 8), new THREE.MeshBasicMaterial({ color: 0x34d399 }));
    prArm.rotation.z = -Math.PI / 4;
    prArm.position.set(0.85, -0.85, 0);
    peaceIconGroup.add(prArm);
    scene.add(peaceIconGroup);

    // Sanctuary Healing Glow Light
    const peaceLight = new THREE.PointLight(0x10b981, 2.8, 70);
    peaceLight.position.set(peaceCenter[0], 8, peaceCenter[1]);
    scene.add(peaceLight);

    // ---------- Union Station sign ----------
    if (unionPoly) {
      // northern-most edge = Front St facade
      let best = 0, bestZ = Infinity;
      const p = unionPoly.pts;
      for (let i = 0; i < p.length; i++) {
        const q = p[(i + 1) % p.length];
        const len = Math.hypot(q[0] - p[i][0], q[1] - p[i][1]);
        const mz = (p[i][1] + q[1]) / 2;
        if (len > 30 && mz < bestZ) { bestZ = mz; best = i; }
      }
      const a = p[best], b = p[(best + 1) % p.length];
      const len = Math.hypot(b[0] - a[0], b[1] - a[1]);
      const nx = (b[1] - a[1]) / len, nz = -(b[0] - a[0]) / len;
      const sign = new THREE.Mesh(
        new THREE.PlaneGeometry(36, 5),
        new THREE.MeshBasicMaterial({ map: makeLabelTexture(['UNION STATION'], { bg: '#1b1b1b', fg: '#ffe9b8', borderColor: '#c9a35b', size: 74, w: 1024, h: 140 }), side: THREE.DoubleSide })
      );
      sign.position.set((a[0] + b[0]) / 2 + nx * 0.6, 16, (a[1] + b[1]) / 2 + nz * 0.6);
      sign.rotation.y = Math.atan2(nx, nz);
      scene.add(sign);
    }

    // ---------- Street lamps (instanced) + pooled real lights ----------
    const lamps = lampSpots.filter(l => canMoveTo(l.x, l.z, 0.3)).slice(0, 700);
    if (lamps.length) {
      const poleGeo = new THREE.CylinderGeometry(0.09, 0.14, 7, 6);
      poleGeo.translate(0, 3.5, 0);
      const headGeo = new THREE.BoxGeometry(0.5, 0.18, 1.1);
      const poles = new THREE.InstancedMesh(poleGeo, new THREE.MeshLambertMaterial({ color: 0x2a2d33 }), lamps.length);
      const heads = new THREE.InstancedMesh(headGeo, new THREE.MeshBasicMaterial({ color: 0xffd08a }), lamps.length);
      const m = new THREE.Matrix4(), q = new THREE.Quaternion(), s = new THREE.Vector3(1, 1, 1), up = new THREE.Vector3(0, 1, 0);
      lamps.forEach((l, i) => {
        m.makeTranslation(l.x, 0, l.z);
        poles.setMatrixAt(i, m);
        q.setFromAxisAngle(up, l.ang);
        const hx = l.x + Math.sin(l.ang) * 0.6, hz = l.z + Math.cos(l.ang) * 0.6;
        m.compose(new THREE.Vector3(hx, 7, hz), q, s);
        heads.setMatrixAt(i, m);
        addCircle(l.x, l.z, 0.25);
      });
      scene.add(poles);
      scene.add(heads);
    }
    const lightPool = [];
    for (let i = 0; i < 6; i++) {
      const pl = new THREE.PointLight(0xffb066, 1.7, 26, 1.6);
      pl.position.set(0, -100, 0);
      scene.add(pl);
      lightPool.push(pl);
    }

    // ---------- Street signs ----------
    const usedNames = {};
    const signs = [];
    signCandidates.forEach(c => {
      if (signs.length > 36) return;
      const prev = usedNames[c.name] || [];
      if (prev.some(p => Math.hypot(p.x - c.x, p.z - c.z) < 150)) return;
      if (!canMoveTo(c.x, c.z, 0.4)) return;
      prev.push(c);
      usedNames[c.name] = prev;
      signs.push(c);
    });
    const signPoleMat = new THREE.MeshLambertMaterial({ color: 0x3a3d44 });
    signs.forEach(c => {
      const g = new THREE.Group();
      const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.06, 3.4, 6), signPoleMat);
      pole.position.y = 1.7;
      g.add(pole);
      const label = c.name.toUpperCase().replace(' STREET', ' ST').replace(' AVENUE', ' AVE').replace(' BOULEVARD', ' BLVD').replace(' EXPRESSWAY', ' EXPY');
      const plate = new THREE.Mesh(
        new THREE.PlaneGeometry(2.6, 0.62),
        new THREE.MeshBasicMaterial({ map: makeLabelTexture(['TORONTO', label], { size: 54 }), side: THREE.DoubleSide })
      );
      plate.position.y = 3.2;
      g.add(plate);
      g.position.set(c.x, 0, c.z);
      g.rotation.y = c.ang;
      scene.add(g);
      addCircle(c.x, c.z, 0.2);
    });

    // ---------- Minimap pre-render ----------
    const MM_SCALE = 0.6; // px per metre
    const mmCanvas = document.createElement('canvas');
    mmCanvas.width = Math.ceil((maxX - minX) * MM_SCALE);
    mmCanvas.height = Math.ceil((maxZ - minZ) * MM_SCALE);
    {
      const g = mmCanvas.getContext('2d');
      const tx = x => (x - minX) * MM_SCALE, tz = z => (z - minZ) * MM_SCALE;
      g.fillStyle = '#16181d';
      g.fillRect(0, 0, mmCanvas.width, mmCanvas.height);
      g.lineCap = 'round';
      MAP.rails.forEach(r => {
        const p = toPairs(r.p);
        g.strokeStyle = '#3a3128'; g.lineWidth = 2;
        g.beginPath(); p.forEach((q, i) => i ? g.lineTo(tx(q[0]), tz(q[1])) : g.moveTo(tx(q[0]), tz(q[1]))); g.stroke();
      });
      MAP.roads.forEach(r => {
        const p = toPairs(r.p);
        g.strokeStyle = r.l && LEVEL_Y[r.t] ? '#7a6a3a' : (MAJOR[r.t] ? '#5b5f69' : '#3a3d45');
        g.lineWidth = Math.max(1.5, r.w * MM_SCALE);
        g.beginPath(); p.forEach((q, i) => i ? g.lineTo(tx(q[0]), tz(q[1])) : g.moveTo(tx(q[0]), tz(q[1]))); g.stroke();
      });
      solids.forEach(s => {
        if (s.type !== 'poly') return;
        g.fillStyle = s.h > 90 ? '#3d5a7a' : '#2c3442';
        g.beginPath(); s.pts.forEach((q, i) => i ? g.lineTo(tx(q[0]), tz(q[1])) : g.moveTo(tx(q[0]), tz(q[1]))); g.closePath(); g.fill();
      });
      g.fillStyle = '#ff3b4a';
      g.beginPath(); g.arc(tx(LM.cnTower[0]), tz(LM.cnTower[1]), 6, 0, Math.PI * 2); g.fill();
    }

    // ---------- Per-frame updates ----------
    let lightTimer = 0, t = 0;
    const towerHue = new THREE.Color();
    function update(dt, playerPos) {
      t += dt;
      // Blink warning lights
      warnLights.visible = (Math.floor(t * 1.1) % 2) === 0;
      // CN Tower colour-cycling LED lighting
      towerHue.setHSL((t * 0.02) % 1, 0.9, 0.5);
      towerMat.emissive.copy(towerHue);

      // Animate Peace Zone Sanctuary
      if (peaceIconGroup) {
        peaceIconGroup.rotation.y += dt * 0.9;
        peaceIconGroup.position.y = 6.5 + Math.sin(t * 1.5) * 0.35;
      }
      if (barrierMat) {
        barrierMat.opacity = 0.22 + Math.sin(t * 2.2) * 0.08;
      }

      // Move pooled lights to nearest lamps
      lightTimer -= dt;
      if (lightTimer <= 0 && lamps.length) {
        lightTimer = 0.35;
        const near = lamps
          .map(l => ({ l, d: (l.x - playerPos.x) ** 2 + (l.z - playerPos.z) ** 2 }))
          .sort((a, b) => a.d - b.d)
          .slice(0, lightPool.length);
        near.forEach((n, i) => {
          const l = n.l;
          lightPool[i].position.set(l.x + Math.sin(l.ang) * 0.6, 6.6, l.z + Math.cos(l.ang) * 0.6);
        });
      }
    }

    function drawMinimap(ctx, size, player, yaw, dots) {
      const radiusM = 110;
      const s = size / (radiusM * 2);
      ctx.save();
      ctx.clearRect(0, 0, size, size);
      ctx.beginPath();
      ctx.arc(size / 2, size / 2, size / 2, 0, Math.PI * 2);
      ctx.clip();
      ctx.fillStyle = '#0d0e12';
      ctx.fillRect(0, 0, size, size);
      ctx.translate(size / 2, size / 2);
      ctx.rotate(yaw); // heading-up
      ctx.scale(s / MM_SCALE, s / MM_SCALE);
      ctx.drawImage(mmCanvas, -(player.x - minX) * MM_SCALE, -(player.z - minZ) * MM_SCALE);
      ctx.restore();

      ctx.save();
      ctx.translate(size / 2, size / 2);
      ctx.rotate(yaw);

      // Draw Peace Zone on the radar (glowing green circle with peace badge)
      const pzx = (peaceCenter[0] - player.x) * s;
      const pzz = (peaceCenter[1] - player.z) * s;
      ctx.fillStyle = 'rgba(16, 185, 129, 0.26)';
      ctx.strokeStyle = '#10b981';
      ctx.lineWidth = 2.5;
      ctx.beginPath();
      ctx.arc(pzx, pzz, PEACE_RADIUS * s, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
      ctx.fillStyle = '#34d399';
      ctx.font = 'bold 9px Arial';
      ctx.textAlign = 'center';
      ctx.fillText('☮ PEACE', pzx, pzz + 3);

      dots.forEach(d => {
        const dx = (d.x - player.x) * s, dz = (d.z - player.z) * s;
        if (dx * dx + dz * dz > (size / 2 - 4) ** 2) return;
        ctx.fillStyle = d.c;
        ctx.beginPath(); ctx.arc(dx, dz, d.r || 3, 0, Math.PI * 2); ctx.fill();
      });
      // CN Tower direction marker on the rim
      const tdx = LM.cnTower[0] - player.x, tdz = LM.cnTower[1] - player.z;
      const td = Math.hypot(tdx, tdz);
      if (td * s > size / 2 - 8) {
        const k = (size / 2 - 8) / td;
        ctx.fillStyle = '#ff3b4a';
        ctx.font = 'bold 10px Arial';
        ctx.textAlign = 'center';
        ctx.save();
        ctx.translate(tdx * k, tdz * k);
        ctx.rotate(-yaw);
        ctx.fillText('CN', 0, 4);
        ctx.restore();
      }
      ctx.restore();

      // player arrow (always points up)
      ctx.fillStyle = '#00f0ff';
      ctx.beginPath();
      ctx.moveTo(size / 2, size / 2 - 7);
      ctx.lineTo(size / 2 - 5, size / 2 + 5);
      ctx.lineTo(size / 2 + 5, size / 2 + 5);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = 'rgba(0,240,255,0.5)';
      ctx.lineWidth = 2;
      ctx.beginPath(); ctx.arc(size / 2, size / 2, size / 2 - 1, 0, Math.PI * 2); ctx.stroke();
      // N marker
      ctx.save();
      ctx.translate(size / 2, size / 2);
      ctx.rotate(yaw);
      ctx.translate(0, -(size / 2 - 10));
      ctx.rotate(-yaw);
      ctx.fillStyle = '#fff';
      ctx.font = 'bold 11px Arial';
      ctx.textAlign = 'center';
      ctx.fillText('N', 0, 4);
      ctx.restore();
    }

    // Player start: at the CN Tower Plaza inside the Peace Sanctuary
    const towerX = LM.cnTower[0];
    const towerZ = LM.cnTower[1];
    const start = findOpenSpot(towerX + 22, towerZ - 18, 0, 10, 2.0);
    const toTower = [towerX - start.x, towerZ - start.z];
    const startYaw = Math.atan2(-toTower[0], -toTower[1]);

    function isInsidePeaceZone(x, z) {
      const dx = x - peaceCenter[0];
      const dz = z - peaceCenter[1];
      return (dx * dx + dz * dz) <= (PEACE_RADIUS * PEACE_RADIUS);
    }

    return {
      canMoveTo,
      findOpenSpot,
      update,
      drawMinimap,
      start,
      startYaw,
      bounds: PLAY,
      landmarks: LM,
      attribution: MAP.attribution,
      peaceZone: {
        x: peaceCenter[0],
        z: peaceCenter[1],
        radius: PEACE_RADIUS
      },
      isInsidePeaceZone
    };
  }

  window.buildTorontoCity = buildTorontoCity;
})();
